    (value)
    {
        public int Size = 1;
    }
    public RandomNode? Root { get; private set; }
    private static int Size(RandomNode? node) => node is null ? 0 : ((SizedNode)node).Size;
    public void Insert(int value)
    {
        var added = new SizedNode(value);
        if (Root is null)
        {
            Root = added;
            return;
        }
        var path = new List<RandomNode>();
        var node = Root;
        while (true)
        {
            path.Add(node);
            if (value <= node.Data)
            {
                if (node.Left is null)
                {
                    node.Left = added;
                    break;
                }
                node = node.Left;
            }
            else
            {
                if (node.Right is null)
                {
                    node.Right = added;
                    break;
                }
                node = node.Right;
            }
        }
        foreach (var ancestor in path)
            ((SizedNode)ancestor).Size++;
    }
    public RandomNode? Find(int value)
    {
        var node = Root;
        while (node is not null)
        {
            if (value == node.Data)
                return node;
            node = value < node.Data ? node.Left : node.Right;
        }
        return null;
    }
    public bool Delete(int value)
    {
        var path = new List<RandomNode>();
        var node = Root;
        while (node is not null && node.Data != value)
        {
            path.Add(node);
            node = value < node.Data ? node.Left : node.Right;
        }
        if (node is null)
            return false;
        if (node.Left is not null && node.Right is not null)
        {
            path.Add(node);
            var successor = node.Right;
            while (successor.Left is not null)
            {
                path.Add(successor);
                successor = successor.Left;
            }
            node.Data = successor.Data;
            node = successor;
        }
        var replacement = node.Left ?? node.Right;
        if (path.Count == 0)
            Root = replacement;
        else
        {
            var parent = path[^1];
            if (ReferenceEquals(parent.Left, node))
