def PlayMinesweeper(bombs: list[list[int]], actions: list[list[int]]) -> list[list[int]]:
    rows, columns = len(bombs), len(bombs[0])
    visible = [[9] * columns for _ in bombs]
    safe = sum(value == 0 for row in bombs for value in row)
    state = 0
