{
    public int MissingNumberBits(BitArray numbers)
    {
        var current = new List<int>();
        for (int i = 0; i < numbers.Size(); ++i)
            current.Add(i);
        int answer = 0, column = 0;
        while (current.Count > 0 && column < 32)
